'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const {WASI} = require('node:wasi');

const [file, kind] = process.argv.slice(2);
const moduleObject = new WebAssembly.Module(fs.readFileSync(file));
const imports = WebAssembly.Module.imports(moduleObject);
const wasi = new WASI({version: 'preview1', args: [], env: {}, preopens: {}});
const instance = new WebAssembly.Instance(moduleObject, wasi.getImportObject());
const {memory, mixer_f05_json_dependency_probe: probe} = instance.exports;
const pages = memory.buffer.byteLength / 65536;
if (instance.exports._initialize) wasi.initialize(instance);
const reactor = Boolean(instance.exports._initialize);
const address = reactor ? (memory.grow(1) + 1) * 65536 - 8192 : 49152;
const bytes = new Uint8Array(memory.buffer);
const ascii = (s) => Buffer.from(s, 'utf8');
const digest = (s) => [...s].reduce((acc, byte) => (Math.imul(acc, 31) + byte) >>> 0, 0);
let pass = 0;
function expect(input, output, canonical) {
    const value = typeof input === 'string' ? ascii(input) : input;
    assert(value.length <= 8192);
    bytes.set(value, address);
    assert.equal(probe(address, value.length) >>> 0, output >>> 0);
    if (canonical) assert.deepEqual(Buffer.from(bytes.slice(address, address+canonical.length)), canonical);
    pass++;
}
function scalar(s, expected) {
    const canonical = ascii(JSON.stringify(expected));
    expect(s, canonical.length, kind === 'scalar-exact' ? canonical : undefined);
}

assert.equal(probe(0, 0), 0);
assert.equal(probe(address, 4097), 0);
assert.equal(probe(address, 0), 0);
if (kind === 'raw' || kind === 'array') {
    for (const input of [Buffer.of(0), Buffer.of(255), ascii('e\u0301🙂'), Buffer.alloc(4096, 255)]) {
        expect(input, digest(input));
    }
} else if (kind === 'task') {
    const prefix = 'revision:18446744073709551615|';
    function vector(flags) {
        const state = Buffer.alloc(9, 255); state[8] = flags;
        return state.toString('base64');
    }
    expect(prefix + vector(0), 1);
    expect(prefix + vector(255), 256);
    expect(prefix + vector(255) + 'x', 0);
    expect(prefix + vector(255).slice(0,-1), 0);
    expect(prefix + '!' + vector(255).slice(1), 0);
    expect('revision:18446744073709551614|' + vector(0), 0);
    expect(prefix + Buffer.alloc(9).toString('base64'), 0);
} else if (kind.startsWith('scalar')) {
    scalar('{"value":""}', '');
    scalar('{"value":"🙂"}', '🙂');
    scalar(String.raw`{"value":"\ud83d\ude42"}`, '🙂');
    scalar(String.raw`{"value":"\u0000\n\t\b\f\r\/\"\\"}`, '\x00\n\t\b\f\r/"\\');
    scalar(String.raw`{"val\u0075e":"e\u0301"}`, 'e\u0301');
    scalar('{"value":"' + 'x'.repeat(4084) + '"}', 'x'.repeat(4084));
    for (const input of [
        '{"value":"x","value":"y"}', String.raw`{"value":"x","val\u0075e":"y"}`,
        String.raw`{"value":"\ud800"}`, String.raw`{"value":"\udc00"}`,
        String.raw`{"value":"\u00xz"}`, '{"value":{"x":"y"}}', '{"value":2}', '{"value":"ok"}x',
        '{"value":"' + 'x'.repeat(4085) + '"}', '{"value":"ok","' + 'x'.repeat(33) + '":1}',
        '{"value":"a","a":1,"b":2,"c":3,"d":4,"e":5,"f":6,"g":7}',
        Buffer.concat([ascii('{"value":"'), Buffer.of(0xc0, 0xaf), ascii('"}')]),
        Buffer.concat([ascii('{"value":"'), Buffer.of(0), ascii('"}')]),
    ]) expect(input,0);
}
console.log(JSON.stringify({kind, passed: pass + 3, initialPages: pages,
    finalPages: memory.buffer.byteLength / 65536, initialized: reactor, imports}));
